SELECT jsonb_build_object(
'authorization_count',(SELECT count(*) FROM platform_private.identity_service_authorization),
'receipt_count',(SELECT count(*) FROM platform_private.identity_service_receipt),
'exact_current_link',EXISTS(SELECT 1 FROM platform_private.identity_service_authorization a JOIN platform_private.identity_service_receipt r ON r.id=a.identity_receipt_id WHERE a.service_principal='ctx01-control-synthetic.v1' AND a.security_generation=2 AND r.id='4bea96c4-5749-5093-b120-82aba41e7c40' AND r.security_generation=a.security_generation AND r.service_principal=a.service_principal AND r.transition='recover' AND r.previous_receipt_id='7133a084-53bf-5f89-9159-f9baf185751c' AND a.revoked_at IS NULL AND r.revoked_at IS NOT DISTINCT FROM a.revoked_at AND r.mutation_transaction_id=a.mutation_transaction_id));
